# Independent owned host metadata preflight; no Docker/Python/archives/science.
param([Parameter(Mandatory=$true)][switch]$RootReviewedSourceAndCard,
 [Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{64}$')][string]$CardSha256,
 [Parameter(Mandatory=$true)][ValidatePattern('^[0-9a-f]{64}$')][string]$OrchestrationHelperSha256)
$ErrorActionPreference='Stop';Set-StrictMode -Version Latest
$researchRoot=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '../..'));$workspaceRoot=[IO.Path]::GetFullPath((Join-Path $researchRoot '..'))
$doc='doc/causal_v11_v13_train_diagnosis/';$sourceRoot='/opt/cuwacunu/research/causal-v11-v13-train-diagnosis/source'
$script:checks=0
function Check([bool]$ok,[string]$why){$script:checks++;if(-not$ok){throw $why}}
function Host-File([string]$relative,[string]$repository='cuwacunu_embedding'){
 Check ($repository-in@('cuwacunu_embedding','cuwacunu_dev')-and-not[IO.Path]::IsPathRooted($relative)-and$relative-notmatch'[\\:]'-and@($relative.Split('/')|Where-Object{$_-in@('','..','.')} ).Count-eq0) 'Explicit bounded repository-relative path'
 $base=[IO.Path]::GetFullPath((Join-Path $workspaceRoot $repository));$path=[IO.Path]::GetFullPath((Join-Path $base $relative));Check ($path.StartsWith($base+[IO.Path]::DirectorySeparatorChar,[StringComparison]::OrdinalIgnoreCase)) 'No repository escape'
 $walk=$path;while($walk-ne$base){$item=Get-Item -LiteralPath $walk;Check (-not($item.Attributes-band[IO.FileAttributes]::ReparsePoint)) 'No linked file/ancestor';$walk=[IO.Path]::GetDirectoryName($walk)};Check (-not(Get-Item -LiteralPath $path).PSIsContainer) 'Physical regular file';return $path
}
function Pin([string]$relative,[string]$repository='cuwacunu_embedding'){$p=Host-File $relative $repository;[ordered]@{path=$relative;bytes=(Get-Item -LiteralPath $p).Length;sha256=(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}}
function Same($a,$b){$a.bytes-eq$b.bytes-and$a.sha256-ceq$b.sha256}
function Equal($a,$b){($a|ConvertTo-Json -Depth 80 -Compress)-ceq($b|ConvertTo-Json -Depth 80 -Compress)}
function Exact($a,$b,[string]$why){Check (@($a).Count-eq@($b).Count-and@($a|Sort-Object -Unique).Count-eq@($b).Count-and-not(Compare-Object @($a|Sort-Object) @($b|Sort-Object))) $why}
$fileMap=[Collections.Generic.Dictionary[string,object]]::new([StringComparer]::Ordinal)
function Record($row){$p=Pin $row.path;Check (Same $p $row) ('Exact metadata/source '+$row.path);if($fileMap.ContainsKey($row.path)){Check (Same $fileMap[$row.path] $p) 'No conflicting full-path inventory duplicate'}else{$fileMap.Add($row.path,$p)};return $p}
Check ([bool]$RootReviewedSourceAndCard) 'Actual card/source root review required'
$destination=Join-Path $PSScriptRoot 'preflight-review.json';Check (-not(Test-Path -LiteralPath $destination)) 'Preserve prior preflight'
$cardRelative='doc/CAUSAL_V11_V13_TRAIN_DIAGNOSIS_CARD.ADMITTED.json';$cardPin=Pin $cardRelative;Check ($cardPin.sha256-ceq$CardSha256) 'External admitted SHA before parse'
$card=Get-Content -LiteralPath (Host-File $cardRelative) -Raw|ConvertFrom-Json
Check ($card.kind-eq'cpb_v11_v13_saved_train_diagnosis_card_v1'-and$card.stage-eq'prospective_before_diagnostic_arithmetic'-and$card.execution_admitted-is[bool]-and$card.execution_admitted-and-not$card.candidate_declared-and-not$card.baseline_or_application_change) 'Separate true admitted card'
Check ((Equal $card.computed_versions @('v13'))-and(Equal $card.cached_reference_versions @('v11'))-and$card.baseline-eq'CPB-v3.market-01'-and$card.train_rows-eq112-and$card.query_rows-eq8-and$card.train_begin_ms-eq1704067259999-and$card.train_end_ms-eq1705881599999-and$card.manual_saved_affine_contractions_declared-and-not$card.module_forwards_allowed-and-not$card.new_quality_or_selection_allowed) 'Fixed TRAIN/no-fit/no-selection scope'
Check (Equal $card.fixed_update_blocks @(@(1,512),@(513,1024),@(1025,1536),@(1537,2048))) 'Fixed update blocks'
$prior=Record $card.separate_root_admission.prospective_card;Check ($prior.path-eq'doc/CAUSAL_V11_V13_TRAIN_DIAGNOSIS_CARD.PROPOSED.json') 'Separate proposed path'
$proposed=Get-Content -LiteralPath (Host-File $prior.path) -Raw|ConvertFrom-Json;Check ($proposed.execution_admitted-is[bool]-and-not$proposed.execution_admitted) 'False prospective preserved'
foreach($property in $proposed.PSObject.Properties){if($property.Name-ne'execution_admitted'){Check (Equal $card.($property.Name) $property.Value) ('Admission preserves field '+$property.Name)}}
Exact @($card.PSObject.Properties.Name) @(@($proposed.PSObject.Properties.Name)+@('separate_root_admission')) 'Only admission object added'
$reviewPin=Record $card.scientific_source_review;$review=Get-Content -LiteralPath (Host-File $reviewPin.path) -Raw|ConvertFrom-Json
Check ($review.kind-eq'causal_v11_v13_diagnosis_source_root_review_v1'-and$review.status-eq'passed_source_review'-and$review.execution_admitted-is[bool]-and-not$review.execution_admitted) 'Combined independent source-only review'
$mainNames=@('archive_reader.py','diagnose.py','schema.py','README.md','provenance.json');$auditNames=@('archive_reader.py','audit.py','component_math.py','README.md','provenance.json')
$expectedScience=@($mainNames|ForEach-Object{'code/research/causal_v11_v13_train_diagnosis/'+$_})+@($auditNames|ForEach-Object{'code/research/causal_v11_v13_train_diagnosis_audit/'+$_})
$helperNames=@('prepare-card.ps1','prepare-preflight.ps1','run-diagnosis.ps1','verify-completion.ps1','orchestration-provenance.json','audit-card-generator.ps1','audit-stage.ps1','audit-execute.py','audit-mirror.ps1','audit-orchestration-provenance.json')
Exact @($review.scientific_files.path) $expectedScience 'Ten complete scientific files with distinct reader full paths';Exact @($review.workflow_files.path) @($helperNames|ForEach-Object{$doc+$_}) 'Ten workflow files'
Check ((Equal $card.scientific_source_files $review.scientific_files)-and(Equal $card.orchestration_helpers $review.workflow_files)-and(Equal $card.closed_design_inventory $review.design)-and(Equal $card.parent_preservation $review.parent_preservation)) 'Card exact reviewed source closure'
Exact @($card.owned_source_files.path) @($mainNames|ForEach-Object{'code/research/causal_v11_v13_train_diagnosis/'+$_}) 'Five main owned paths'
foreach($row in @($review.scientific_files)+@($review.workflow_files)){Record $row|Out-Null}
$helper=Pin ($doc+'run-diagnosis.ps1');Check ($helper.sha256-ceq$OrchestrationHelperSha256) 'External phased-helper SHA'
$inventoryPin=Record $card.closed_design_inventory;$parentsPin=Record $card.parent_preservation;$planPin=Record $card.completed_context_plan
$inventory=Get-Content -LiteralPath (Host-File $inventoryPin.path) -Raw|ConvertFrom-Json;$plan=Get-Content -LiteralPath (Host-File $planPin.path) -Raw|ConvertFrom-Json
Check ($plan.kind-eq'cpb_v11_v13_diagnosis_completed_context_plan_v1'-and$plan.status-eq'root_reviewed_completed_inputs'-and$plan.authorized_execution-is[bool]-and-not$plan.authorized_execution) 'Frozen metadata-only context plan'
$cache=@('cached_v11_TRAIN.stages.initial','cached_v11_TRAIN.stages.final','cached_v11_TRAIN.temporal_moment_observations.csv','cached_v11_TRAIN.temporal_moment_observations.actual_witnesses');Check (Equal $card.cached_v11_selectors $cache) 'Four actual cached V11 selectors in latest completed diagnosis'
Exact @($card.allowed_inputs.id) @($inventory.prospective_numeric_roles.id) 'Exact25 numeric IDs';Check ($card.allowed_inputs.Count-eq25) 'Twenty-five numeric roles'
foreach($row in $card.allowed_inputs){$source=@($inventory.prospective_numeric_roles|Where-Object id -eq $row.id);Check ($source.Count-eq1) 'One design role';$s=$source[0];$hostPath=if($s.PSObject.Properties.Name-contains'host_path'){$s.host_path}else{$s.path};$runtime=if($row.id-eq'cached_v11_prior_TRAIN_diagnosis'){$sourceRoot+'/preservation/cached-v11-diagnosis.json'}else{$s.container_path};Check ($row.role-ceq$s.role-and$row.host_repository-ceq$s.host_repository-and$row.host_path-ceq$hostPath-and$row.path-ceq$hostPath-and$row.container_path-ceq$runtime-and(Same $row $s)) 'Exact declared numeric identity and explicit transport path';if($row.id-eq'cached_v11_prior_TRAIN_diagnosis'){Check (Equal $row.numeric_json_selectors $cache) 'Cache selectors only'}elseif($row.id-eq'v13_temporal_moment_csv'){Check (Equal $row.allowed_CSV_columns $s.allowed_CSV_columns) 'Eleven CSV columns'}elseif($row.id.EndsWith('_query_summary')){Check (Equal $row.numeric_json_selectors @('train')) 'TRAIN mixed JSON only'}else{Exact @($row.allowed_tensor_fields) @($s.allowed_tensor_fields) 'Exact typed/tensor selector set'}}
$guardSource=@($inventory.historical_V11_hash_only_guard_roles)+@($inventory.additional_V13_hash_only_guard_roles);Exact @($card.hash_only_guards.id) @($guardSource.id) 'Exact35 guard IDs';Check ($card.hash_only_guards.Count-eq35) 'Thirty-five hash guards'
foreach($row in $card.hash_only_guards){$s=@($guardSource|Where-Object id -eq $row.id)[0];$hostPath=if($s.PSObject.Properties.Name-contains'host_path'){$s.host_path}else{$s.path};Check ($row.role-eq'hash_only_no_numeric_access'-and$row.host_repository-ceq$s.host_repository-and$row.host_path-ceq$hostPath-and$row.path-ceq$hostPath-and$row.container_path-ceq$s.container_path-and(Same $row $s)) 'Exact guard paths/bytes with declared path fallback'}
Check ((Equal $card.context_inputs $plan.context_inputs)-and$card.context_inputs.Count-eq14-and(Equal $card.context_assertions $plan.context_assertions)-and(Equal $card.context_assertions $inventory.prospective_context_assertions)-and$card.context_assertions-is[array]-and$card.context_assertions.Count-eq12-and(Equal $card.pre_execution_preservation $plan.pre_execution_preservation)-and(Equal $card.preservation_pins $plan.preservation_pins)) 'Exact14 context/12 ARRAY assertions/dedicated fresh preservation'
$all=@($card.allowed_inputs)+@($card.hash_only_guards)+@($card.context_inputs)+@($card.preservation_pins)+@($card.pre_execution_preservation);$byHost=@{};$byRuntime=@{};$verified=@()
foreach($row in $all){Check ($row.container_path.StartsWith('/')-and$row.container_path-notmatch'(^|/)\.\.(/|$)|\\'-and$row.bytes-gt0-and$row.sha256-cmatch'^[0-9a-f]{64}$') 'Typed normal absolute binding';$key=$row.host_repository+'/'+$row.host_path;if($byHost.ContainsKey($key)){Check (Same $byHost[$key] $row) 'Host alias exact'}else{$actual=Pin $row.host_path $row.host_repository;Check (Same $actual $row) 'Current file availability/bytes/hash';$byHost[$key]=$actual};if($byRuntime.ContainsKey($row.container_path)){Check (Same $byRuntime[$row.container_path] $row) 'Runtime alias exact'}else{$byRuntime[$row.container_path]=$row};$verified+=$row}
Check ($all.Count-eq$card.logical_pin_occurrences-and$byHost.Count-eq$card.unique_host_files-and$byRuntime.Count-eq$card.unique_container_files) 'Derived logical/physical alias counts'
$cacheRow=@($card.allowed_inputs|Where-Object id -eq 'cached_v11_prior_TRAIN_diagnosis');Check ($cacheRow.Count-eq1) 'One exact opaque cache role'
$copies=@($cacheRow)+@($card.context_inputs)+@($card.pre_execution_preservation);Check ($copies.Count-eq16-and(Equal $card.metadata_copies_required_before_execution $copies)) 'Explicit cache1/context14/fresh preservation1 copies'
$contexts=@{};foreach($row in $card.context_inputs){Check ($row.container_path-eq($sourceRoot+'/preservation/'+$row.id+'.json')) 'Exact staged context path';$contexts[$row.id]=Get-Content -LiteralPath (Host-File $row.host_path $row.host_repository) -Raw|ConvertFrom-Json}
foreach($assertion in $card.context_assertions){$v=$contexts[$assertion.input];foreach($key in $assertion.path){Check ($key-is[string]-and$key) 'Literal assertion selector';$v=$v.$key};Check (Equal $v $assertion.equals) ('Typed context assertion '+$assertion.id)}
$pre=$card.pre_execution_preservation;Check ($pre.container_path-eq($sourceRoot+'/preservation/pre-execution-preservation.json')) 'Separate fresh-preservation runtime path';$fresh=Get-Content -LiteralPath (Host-File $pre.host_path) -Raw|ConvertFrom-Json
$final=$contexts.v13_final_preservation;Check ($final.status-eq'passed'-and$final.critical_checkpoint_total-eq119-and$final.V13_source_files-eq143-and-not$final.application_changed-and-not$final.baseline_changed-and$fresh.status-eq'passed'-and$fresh.critical_checkpoint_count-eq119-and$fresh.all_availability_bytes_sha256_exact-and(Same $fresh.parent_final_preservation @($card.context_inputs|Where-Object id -eq 'v13_final_preservation')[0])) 'Reuse completed119/143 and fresh119 exact receipt; no broad verifier replay'
# Current source-owned ignore check uses argv batches, avoiding PowerShell CRLF stdin ambiguity.
$ignoreEvidence=@();foreach($repository in @('cuwacunu_embedding','cuwacunu_dev')){$paths=@($all|Where-Object{$_.host_repository-eq$repository-and$_.host_path.EndsWith('.pt')}|ForEach-Object host_path|Sort-Object -Unique);if($paths.Count){$root=[IO.Path]::GetFullPath((Join-Path $workspaceRoot $repository));$ignored=@();for($begin=0;$begin-lt$paths.Count;$begin+=128){$batch=@($paths|Select-Object -Skip $begin -First 128);$ignored+=@(& git.exe -c ('safe.directory='+$root.Replace([char]92,[char]47)) -C $root check-ignore --no-index -- @batch);Check ($LASTEXITCODE-eq0) 'Declared PT ignored in bounded argv batch'};Exact $ignored $paths 'Exact returned declared ignore paths';$ignoreEvidence+=[ordered]@{repository=$repository;declared_PT=$paths.Count;all_ignored=$true}}}
Record $cardPin|Out-Null;Record (Pin $cardRelative.Replace('.json','.md'))|Out-Null;Record (Pin $prior.path.Replace('.json','.md'))|Out-Null
$expected=@($expectedScience)+@($helperNames|ForEach-Object{$doc+$_})+@($reviewPin.path,$inventoryPin.path,$parentsPin.path,$planPin.path,$prior.path,$cardPin.path,$cardRelative.Replace('.json','.md'),$prior.path.Replace('.json','.md'))
$expected=@($expected|Sort-Object -Unique);$files=@($fileMap.Keys|Sort-Object|ForEach-Object{$fileMap[$_]});Exact @($files.path) $expected 'Exact full-path inventory; no OrderedDictionary Group-Object loss'
$result=[ordered]@{kind='cpb_v11_v13_saved_TRAIN_diagnosis_independent_static_preflight_v1';status='passed';checks=$script:checks;card_sha256=$CardSha256;card=$cardPin;prospective_card=$prior;files=$files;orchestration_helper=$helper;source_review=$reviewPin;allowed_input_pins=25;hash_only_guards=35;metadata_contexts=14;metadata_copies=$copies.Count;logical_pin_occurrences=$all.Count;unique_host_files=$byHost.Count;unique_container_files=$byRuntime.Count;verified_file_bindings=$verified;pre_execution_preservation=$pre;reused_completed_checkpoint_count=119;checkpoint_archives_rehashed_by_this_preflight=0;declared_PT_ignore=$ignoreEvidence;root_review_of_exact_source_card_acknowledged=$true;actions=[ordered]@{Docker=0;AST=0;imports=0;numeric_storage_reads=0;models=0;heads=0;training_updates=0;DEV_writes=0}}
$stream=[IO.File]::Open($destination,[IO.FileMode]::CreateNew,[IO.FileAccess]::Write);try{$b=[Text.UTF8Encoding]::new($false).GetBytes(($result|ConvertTo-Json -Depth 80).Replace([string][char]13,'')+[char]10);$stream.Write($b,0,$b.Length)}finally{$stream.Dispose()};Pin ($doc+'preflight-review.json')|ConvertTo-Json
